nta.declaration:
// Standalone network test. It is separate from the group's mission/command model (03a)
// and not connected to it yet.
// One time unit = 100 ms. All numbers here are test values, not MAVLink defaults.
const int N_PRODUCERS = 2;           // test senders
const int N_ENDPOINTS = 2;           // receivers 0 and 1
const int PACKETS_PER_PRODUCER = 2;
const int N_PACKETS = N_PRODUCERS * PACKETS_PER_PRODUCER;
const int D_MIN = 1;                 // earliest delivery or loss after the link takes a packet
const int D_MAX = 3;                 // latest delivery or loss after the link takes a packet
// Loss setting: 0 = reliable, 1 = any packet can be lost,
// 2 = at most K_LOSS losses in a row for each producer
const int LOSS_MODE = 1;
const int K_LOSS = 1;

typedef int[0,N_PRODUCERS-1] producer_id;
typedef int[0,N_ENDPOINTS-1] endpoint_id;
typedef int[0,N_PACKETS-1] packet_id;
typedef int[0,1] kind_id;            // two abstract traffic classes, not real MAVLink messages
typedef int[0,9] payload_t;          // small value, only used to check the contents arrive unchanged
// id is only for test bookkeeping, it is not a MAVLink field
typedef struct { packet_id id; endpoint_id src; endpoint_id dst;
                 kind_id kind; payload_t payload; } packet_t;

// Each producer has its own place to put a packet while it waits.
packet_t outgoing[N_PRODUCERS];
// Written by the network on the delivery edge, read by the receiver in the same step.
packet_t incoming;
// urgent chan: when the link is free and a packet is waiting, the link takes it
// straight away (time cannot pass). Time can still pass while the link is busy.
urgent chan net_tx[N_PRODUCERS];     // producer p -> network
chan net_rx[N_ENDPOINTS];            // network -> receiver with that id

// Test bookkeeping, only used by the queries. A real sender never sees these values.
// Packet IDs are used once.
// status: 0 = not taken by the link yet, 1 = in flight, 2 = delivered, 3 = lost
int[0,3] status[N_PACKETS];
packet_t expected[N_PACKETS];        // copy of each packet as the producer made it
int[0,2] deliveries[N_PACKETS];      // range goes to 2 so a duplicate shows up in N5 instead of a range error
bool integrityError = false;         // set by a receiver if a packet arrives wrong
bool pending[N_PRODUCERS];           // producer p has a packet waiting for the link
int[0,K_LOSS] consecutiveLoss[N_PRODUCERS];  // losses in a row per producer (only counted in mode 2)
int[0,N_PACKETS] admitted = 0;
int[0,N_PACKETS] delivered = 0;
int[0,N_PACKETS] lost = 0;

template.declaration:
// The shared link. It holds one packet at a time, in either direction.
// Idle -> Transmitting: take a waiting packet, copy it, reset x.
// Transmitting -> Delivered: after D_MIN, hand the copy to the receiver.
// Transmitting -> Lost: after D_MIN, only if LOSS_MODE allows it. Nobody is told.
// Delivered and Lost are committed, so the slot is free again straight away.
// x <= D_MAX means delivery or loss must happen by D_MAX. This only works because
// the test receiver is always ready, otherwise the model could get stuck here.
clock x;                 // time since the link took the packet
packet_t packet;         // the link's own copy of the packet in flight
producer_id owner = 0;   // who sent it (used for the loss counter)

// Test sender p. It makes PACKETS_PER_PRODUCER packets, one after the other.
// Producer 0 sends to receiver 1 and producer 1 to receiver 0, so both directions
// share the link.
// Prepare is urgent so the test makes its next packet straight away.
// The waiting for the link happens in Waiting, where time can pass.
int[0,PACKETS_PER_PRODUCER] next = 0;  // packets already handed to the link
clock wait;                            // time spent in Waiting (admission wait, measured by N18)

// Test receiver stub. It is always ready, so a delivery is never blocked.
// It checks the packet against the producer's copy and that it was not delivered before.
// It does no application work and sends no ACK.

nta.system:
// Link is the network being tested. The senders and receivers are only the test harness.
Link = Network();
Sender0 = Producer(0);
Sender1 = Producer(1);
Receiver0 = Receiver(0);
Receiver1 = Receiver(1);
system Link, Sender0, Sender1, Receiver0, Receiver1;
